insert into public.cases (id, title, description, chain, status, priority, is_sample, created_at) values
  ('ea931542-133f-86c9-a6cd-3c87a270b628', 'Ghost Attacks: Halcyon Bridge exploit', 'An attacker deployed a contract that drained 12,110 ETH and 12.94M USDC (about $42M at the sample reference price) from the Halcyon Bridge vault in three calls. Proceeds were swapped to ETH, split across four fresh wallets within seven minutes, then routed through a mixer, a peel chain into two exchanges, a cross-chain bridge and an OTC desk.', 'Ethereum', 'Active', 'Critical', true, '2026-09-14T03:05:00.000Z'),
  ('cb821f25-fa66-8216-b73f-1b784b194816', 'Approval-drainer phishing wave', 'Three victims signed malicious token approvals on a fake mint page. A drainer contract pulled their funds and split each haul 80/20 between an operator wallet and an affiliate wallet. The operator consolidated and sent part to an exchange deposit.', 'Ethereum', 'Monitoring', 'High', true, '2026-09-21T16:00:00.000Z')
