insert into public.wallet_clusters (id, case_id, name, description, method) values
  ('7ac72bc2-b39d-8f6f-877c-df9915d555fd', 'ea931542-133f-86c9-a6cd-3c87a270b628', 'Exploiter-controlled set', 'The exploiter funded G1, and G1 alone made the first deposit (0.05 ETH gas) into each of H1 to H4 within four minutes. Each hop wallet was then loaded by the exploiter within seven minutes.', 'Gas-funding linkage'),
  ('f74a4a5c-5f44-81d1-bbc3-c524400236ec', 'ea931542-133f-86c9-a6cd-3c87a270b628', 'Northgate Exchange', 'X1 forwards its entire balance to the Northgate hot wallet, which is how exchange deposit addresses behave. Corroborated by Northgate''s freeze notice (OS-05).', 'Deposit-address sweep'),
  ('7a0b5e35-9725-87dc-a61c-e319443dde82', 'ea931542-133f-86c9-a6cd-3c87a270b628', 'Kestrel Exchange', 'X2 forwards its full 385 ETH balance to the Kestrel hot wallet 31 minutes after receipt.', 'Deposit-address sweep'),
  ('968fca96-752d-844c-bcf0-304c7d6fdde9', 'ea931542-133f-86c9-a6cd-3c87a270b628', 'Peel chain', 'Each wallet received one input, peeled a small amount to an exchange deposit, and forwarded more than 90% to a new wallet within 25 minutes.', 'Sequential peel pattern'),
  ('e3a19f81-f86f-8f7c-b90e-7333a98b43f2', 'cb821f25-fa66-8216-b73f-1b784b194816', 'Drainer split recipients', 'Every drained amount is split 80/20 between the same two wallets in the same transaction.', 'Fixed-ratio split from one contract')
